const MA_COLS = [['เลขทะเบียน', 230, 'Lead text'], ['ประเภทยานพาหนะ', 170], ['บำรุงรักษาล่าสุด', 150], ['เลขไมล์', 140], ['น้ำมันไฮโดรลิก', 170], ['Safety Inspection', 150], ['กำหนดครั้งถัดไป', 0], ['', 64]];
